    vertical_color = min(colors, key=lambda c: (len(info[c]["cols"]) - len(info[c]["rows"]), len(info[c]["cols"])))
    horizontal_color = max(colors, key=lambda c: (len(info[c]["cols"]) - len(info[c]["rows"]), len(info[c]["rows"])))

    # If this heuristic picked the same color somehow, fall back to the first two colors.
    if vertical_color == horizontal_color:
        vertical_color, horizontal_color = colors[:2]

