                horizontal_gaps += 1

    out = [row[:] for row in grid]

    # Fill the intersection to complete whichever shape is interrupted.
    if vertical_gaps > 0 and horizontal_gaps == 0:
        fill_color = vertical_color
    elif horizontal_gaps > 0 and vertical_gaps == 0:
        fill_color = horizontal_color
    else:
        # Fallback: fill the shape with more gaps.
        fill_color = vertical_color if vertical_gaps >= horizontal_gaps else horizontal_color

    for r in h_rows:
        for c in v_cols:
            out[r][c] = fill_color

    return out

